-- Apply on Supabase before enabling BOOKING_TWO_STEP on Web.
-- Laravel is the only writer of inspection data; mobile can acknowledge one
-- current revision and cannot change the inspected items or fees.
CREATE TABLE IF NOT EXISTS public."BookingGiaoNhan" (
  "BookingGiaoNhanID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "BookingID" integer NOT NULL REFERENCES public."Booking"("BookingID") ON DELETE CASCADE,
  "DonHangID" integer REFERENCES public."DonHang"("DonHangID") ON DELETE SET NULL,
  "BookingKiemKeID" integer,
  "LoaiGiaoNhan" varchar(30) NOT NULL CHECK ("LoaiGiaoNhan" IN ('NHAN_DO', 'GIAO_DO')),
  "HinhThuc" varchar(30) NOT NULL CHECK ("HinhThuc" IN ('Tại nhà', 'Tại cửa hàng')),
  "DiaChi" varchar(255),
  "NhanVienID" integer REFERENCES public."NhanVien"("NhanVienID") ON DELETE SET NULL,
  "ThoiGianDuKien" timestamp,
  "ThoiGianThucTe" timestamp,
  "PhiGiaoNhan" numeric(12,2) NOT NULL DEFAULT 0 CHECK ("PhiGiaoNhan" >= 0),
  "TrangThai" varchar(30) NOT NULL DEFAULT 'Chờ thực hiện',
  "NgayTao" timestamp NOT NULL DEFAULT now(),
  UNIQUE ("BookingID", "LoaiGiaoNhan")
);

CREATE TABLE IF NOT EXISTS public."BookingKiemKe" (
  "BookingKiemKeID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "BookingID" integer NOT NULL UNIQUE REFERENCES public."Booking"("BookingID") ON DELETE CASCADE,
  "DuLieuThucTe" jsonb NOT NULL,
  "CoChenhLech" boolean NOT NULL,
  "PhienBan" integer NOT NULL DEFAULT 1 CHECK ("PhienBan" >= 1),
  "XacNhanPhienBan" integer,
  "XacNhanLuc" timestamp,
  "CapNhatLuc" timestamp NOT NULL DEFAULT now()
);

ALTER TABLE public."BookingGiaoNhan" ADD CONSTRAINT booking_delivery_inspection_fk
  FOREIGN KEY ("BookingKiemKeID") REFERENCES public."BookingKiemKe"("BookingKiemKeID") ON DELETE SET NULL;
CREATE INDEX IF NOT EXISTS booking_delivery_order_idx ON public."BookingGiaoNhan" ("DonHangID");
CREATE INDEX IF NOT EXISTS booking_delivery_inspection_idx ON public."BookingGiaoNhan" ("BookingKiemKeID");

ALTER TABLE public."BookingGiaoNhan" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."BookingKiemKe" ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public."BookingGiaoNhan", public."BookingKiemKe" FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public."BookingGiaoNhan", public."BookingKiemKe" TO authenticated;
GRANT UPDATE ("XacNhanPhienBan") ON public."BookingKiemKe" TO authenticated;

CREATE POLICY booking_delivery_customer_read ON public."BookingGiaoNhan"
  FOR SELECT TO authenticated USING (EXISTS (
    SELECT 1 FROM public."Booking" booking
    WHERE booking."BookingID" = "BookingGiaoNhan"."BookingID"
      AND booking."KhachHangID" = (SELECT private.current_customer_id())
  ));

CREATE POLICY booking_inspection_customer_read ON public."BookingKiemKe"
  FOR SELECT TO authenticated USING (EXISTS (
    SELECT 1 FROM public."Booking" booking
    WHERE booking."BookingID" = "BookingKiemKe"."BookingID"
      AND booking."KhachHangID" = (SELECT private.current_customer_id())
  ));

CREATE POLICY booking_inspection_customer_ack ON public."BookingKiemKe"
  FOR UPDATE TO authenticated USING (
    "CoChenhLech" AND "XacNhanPhienBan" IS NULL
    AND EXISTS (SELECT 1 FROM public."Booking" booking
      WHERE booking."BookingID" = "BookingKiemKe"."BookingID"
        AND booking."KhachHangID" = (SELECT private.current_customer_id()))
  ) WITH CHECK (
    "CoChenhLech" AND "XacNhanPhienBan" = "PhienBan"
    AND EXISTS (SELECT 1 FROM public."Booking" booking
      WHERE booking."BookingID" = "BookingKiemKe"."BookingID"
        AND booking."KhachHangID" = (SELECT private.current_customer_id()))
  );

CREATE OR REPLACE FUNCTION private.stamp_booking_inspection_ack()
RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN
  IF NEW."XacNhanPhienBan" IS DISTINCT FROM OLD."XacNhanPhienBan" THEN
    IF NEW."XacNhanPhienBan" IS NOT NULL THEN
      IF NOT OLD."CoChenhLech" OR OLD."XacNhanPhienBan" IS NOT NULL
         OR NEW."XacNhanPhienBan" <> OLD."PhienBan"
         OR NEW."PhienBan" <> OLD."PhienBan" THEN
        RAISE EXCEPTION 'Stale or invalid Booking inspection approval' USING ERRCODE = '23514';
      END IF;
      NEW."XacNhanLuc" := now();
    ELSIF NEW."PhienBan" <= OLD."PhienBan" THEN
      RAISE EXCEPTION 'Inspection approval can only reset for a new revision' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION private.stamp_booking_inspection_ack() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS stamp_booking_inspection_ack ON public."BookingKiemKe";
CREATE TRIGGER stamp_booking_inspection_ack BEFORE UPDATE ON public."BookingKiemKe"
  FOR EACH ROW EXECUTE FUNCTION private.stamp_booking_inspection_ack();
